input.command:
cd /home/user/rork-app
export OWNER_TOKEN=$(cat /tmp/owner_at 2>/dev/null || echo "")
if [ -z "$OWNER_TOKEN" ]; then
  curl -s -X POST https://api.ivxholding.com/api/ivx/owner-passwordless-login \
    -H "Content-Type: application/json" -d '{"email":"iperez4242@gmail.com"}' -o /tmp/login.json
  node -e "const d=JSON.parse(require('fs').readFileSync('/tmp/login.json','utf8')); require('fs').writeFileSync('/tmp/owner_at', d.accessToken);"
  export OWNER_TOKEN=$(cat /tmp/owner_at)
fi

node <<'NODE'
const ownerToken = require('fs').readFileSync('/tmp/owner_at','utf8').trim();
const HOST = 'https://api.ivxholding.com';

async function probe(method, path, body, opts={}) {
  const headers = {'Content-Type':'application/json'};
  if (ownerToken) headers['Authorization'] = `Bearer ${ownerToken}`;
  if (opts.extraHeaders) Object.assign(headers, opts.extraHeaders);
  const start = Date.now();
  try {
    const init = {method, headers};
    if (body) init.body = JSON.stringify(body);
    const res = await fetch(HOST+path, init);
    const elapsed = Date.now()-start;
    let parsed = null;
    const text = await res.text();
    try { parsed = JSON.parse(text); } catch {}
    return {ok:res.ok, status:res.status, ms:elapsed, len:text.length, body:parsed||text.slice(0,300), ct:res.headers.get('content-type')};
  } catch(e) {
    return {error:e.message, ms:Date.now()-start};
  }
}

(async () => {
