  b.push(['AGENTS', 'GET /api/ivx/agent-jobs/live-activity', await probe('GET','/api/ivx/agent-jobs/live-activity')]);
  b.push(['AGENTS', 'GET /api/ivx/agents/parallel/list', await probe('GET','/api/ivx/agents/parallel/list')]);
  b.push(['ACTION_LOOP', 'GET /api/ivx/action-loop', await probe('GET','/api/ivx/action-loop')]);

  // ===== AUTH / ACCESS =====
  b.push(['ACCESS', 'GET /api/ivx/access/status', await probe('GET','/api/ivx/access/status')]);
  b.push(['ACCESS', 'GET /api/ivx/access/mfa', await probe('GET','/api/ivx/access/mfa')]);
  b.push(['ACCESS', 'GET /api/ivx/access/groups', await probe('GET','/api/ivx/access/groups')]);
  b.push(['ACCESS', 'GET /api/ivx/access/screens', await probe('GET','/api/ivx/access/screens')]);
  b.push(['ACCESS', 'GET /api/ivx/access/templates', await probe('GET','/api/ivx/access/templates')]);

