  b.push(['CERT_APP', 'GET /api/cert-app/health', await probe('GET','/api/cert-app/health')]);
  b.push(['CERT_APP', 'GET /api/cert-app/readiness', await probe('GET','/api/cert-app/readiness')]);

  // ===== PRINT =====
  let pass=0, fail=0, err=0;
  const byCat = {};
  for (const [cat, label, r] of b) {
    if (r.error) { err++; byCat[cat] = (byCat[cat]||{p:0,f:0,e:0}); byCat[cat].e++; }
    else if (r.ok) { pass++; byCat[cat] = (byCat[cat]||{p:0,f:0,e:0}); byCat[cat].p++; }
    else { fail++; byCat[cat] = (byCat[cat]||{p:0,f:0,e:0}); byCat[cat].f++; }
  }
  console.log('=== BATCH 1 SUMMARY ===');
  console.log('total:', b.length, 'pass:', pass, 'fail:', fail, 'error:', err);
  console.log('by category:', JSON.stringify(byCat, null, 2));

  console.log('\n=== FAILURES / ERRORS DETAIL ===');
  for (const [cat, label, r] of b) {
    if (r.error || !r.ok) {
