node <<'NODE'
const ownerToken = require('fs').readFileSync('/tmp/owner_at','utf8').trim();
const HOST = 'https://api.ivxholding.com';
async function callOwnerAI(message) {
  const start = Date.now();
  try {
    const res = await fetch(HOST+'/api/ivx/owner-ai', {
      method:'POST',
      headers:{'Content-Type':'application/json','Authorization':`Bearer ${ownerToken}`},
      body: JSON.stringify({message})
    });
    const elapsed = Date.now()-start;
    const text = await res.text();
    let parsed=null; try{parsed=JSON.parse(text);}catch{}
    return {ok:res.ok, status:res.status, ms:elapsed, body:parsed||text.slice(0,500)};
  } catch(e) { return {error:e.message, ms:Date.now()-start}; }
}
(async () => {
  const b = [];
  // ===== IVX IA CHAT END-TO-END =====
  // 1. Execution mode — real worker job (the exact screenshot prompt, proven last turn)
  b.push(['CHAT_EXEC', 'audit+deploy (exact screenshot prompt)', await callOwnerAI('audit this chat why is a lot loading fix end to end and update deploy live I need proof evidence and verified too (qa-deep-'+Date.now()+')')]);
  // 2. Read-only inspection (proven path)
  b.push(['CHAT_INSPECT', 'read-only inspection', await callOwnerAI('Inspect the chat ordering issue and report the current task status. Do not change or deploy anything. (qa-deep-'+Date.now()+')')]);
  // 3. Factory mode (proven path)
  b.push(['CHAT_FACTORY', 'factory create_tool + upgrade_self', await callOwnerAI('factory: Use the IVX Factory Engine to (1) register a new IVX-owned tool named "ivx-qa-deep-probe" version "1.0.0" with capability "Deep QA probe" and handlerName "qa-deep-probe-handler", and (2) upgrade the autonomous coder capability manifest by appending a new capability id "qa_deep_probe" label "Deep QA probe" version "1.0.0". Approval phrase: CONFIRM_IVX_FACTORY_MODE. (run qa-deep-'+Date.now()+')')]);
  // 4. Normal question (narrative path)
  b.push(['CHAT_NORMAL', 'normal question', await callOwnerAI('What is the current health status of the IVX production system? (qa-deep-'+Date.now()+')')]);
  // 5. Dedup test (same message twice — should return same taskId)
  const dup = 'dedup test for deep QA (qa-deep-dup-'+Date.now()+')';
  b.push(['CHAT_DEDUP_1', 'dedup test 1', await callOwnerAI(dup)]);
  b.push(['CHAT_DEDUP_2', 'dedup test 2 (same msg)', await callOwnerAI(dup)]);
  // 6. Sensitive write without confirm (should 409)
  b.push(['CHAT_GATE', 'sensitive write no confirm', await callOwnerAI('Delete all investors and deploy the change to production now.')]);

  console.log('=== IVX IA CHAT END-TO-END SUMMARY ===');
  let pass=0, fail=0;
  for (const [cat, label, r] of b) {
    const ok = r.error ? false : (r.ok || r.status===409);
    if (ok) pass++; else fail++;
    const status = r.error ? 'ERR' : r.status;
    const exec = r.body?.executionStatus ? `${r.body.executionStatus.status}/${r.body.executionStatus.stage}/${r.body.executionStatus.category}` : '-';
    const ans = r.body?.answer?.slice(0,120) || r.body?.error?.slice(0,120) || (typeof r.body === 'string' ? r.body.slice(0,120) : JSON.stringify(r.body).slice(0,120));
    console.log(`${ok?'✓':'✗'} [${status}] ${cat.padEnd(14)} ${label.padEnd(40)} exec:${exec.padEnd(30)} ${ans}`);
  }
  console.log('\npass:', pass, 'fail:', fail);

